import { test as base, expect } from "@playwright/test";
import { Pool } from "pg";
import { requireTestDatabaseUrl } from "./foundation-db";

export const test = base.extend<{ systemControl: void }>({
  systemControl: [
    async ({}, runFixture) => {
      if (process.env.MAILLOOP_E2E_ISOLATED !== "1")
        throw new Error(
          "Run browser tests using the disposable database runner.",
        );
      requireTestDatabaseUrl();
      const pool = new Pool({ connectionString: process.env.DATABASE_URL });
      const result = await pool.query(
        `SELECT row_to_json(control) AS snapshot FROM "SystemControl" AS control WHERE key='global'`,
      );
      const previous = result.rows[0]?.snapshot as
        Record<string, unknown> | undefined;
      if (!previous) throw new Error("Missing initialized SystemControl.");
      try {
        // Tests explicitly opt into quota gating. Never inherit another test's state.
        await pool.query(
          `UPDATE "SystemControl" SET "sendingEnabled"=true,"paidGatingEnabled"=false WHERE key='global'`,
        );
        await runFixture();
      } finally {
        const assignments = Object.keys(previous)
          .filter((name) => name !== "id")
          .map((name) => `"${name}"=snapshot."${name}"`)
          .join(",");
        try {
          await pool.query(
            `UPDATE "SystemControl" AS control SET ${assignments} FROM json_populate_record(NULL::"SystemControl",$1::json) AS snapshot WHERE control.key='global'`,
            [JSON.stringify(previous)],
          );
        } finally {
          await pool.end();
        }
      }
    },
    { auto: true },
  ],
});
export { expect };
